SELECT "brokerid", "managerid", "firstname", "lastname", "middleinitial", "branch", "office", "phone", "iscurrent", "batchid", "effectivedate", "enddate", CAST(ROW_NUMBER() OVER (ORDER BY brokerid) AS INT) AS "sk_brokerid" FROM (SELECT TRY_CAST((CAST(h.EmployeeID AS INT)) AS INT) AS "brokerid", TRY_CAST((CAST(h.ManagerID AS INT)) AS INT) AS "managerid", TRY_CAST((CAST(h.EmployeeFirstName AS TEXT)) AS TEXT) AS "firstname", TRY_CAST((CAST(h.EmployeeLastName AS TEXT)) AS TEXT) AS "lastname", TRY_CAST((CAST(h.EmployeeMI AS TEXT)) AS TEXT) AS "middleinitial", TRY_CAST((CAST(h.EmployeeBranch AS TEXT)) AS TEXT) AS "branch", TRY_CAST((CAST(h.EmployeeOffice AS TEXT)) AS TEXT) AS "office", TRY_CAST((CAST(h.EmployeePhone AS TEXT)) AS TEXT) AS "phone", TRY_CAST((CAST(TRUE AS BOOLEAN)) AS BOOLEAN) AS "iscurrent", TRY_CAST((CAST(NULL AS INT)) AS INT) AS "batchid", TRY_CAST((CAST(NULL AS DATE)) AS DATE) AS "effectivedate", TRY_CAST((CAST('9999-12-31' AS DATE)) AS DATE) AS "enddate" FROM "Source"."HR" AS h);
